import { expect, test, type Page } from '@playwright/test';

// The engine on real ffmpeg.wasm (5.1.4) in Firefox. Test media is generated by ffmpeg.wasm
// itself; the page imports the engine modules from the dev server.

test.describe.configure({ mode: 'serial', timeout: 240_000 });

let page: Page;

test.beforeAll(async ({ browser }) => {
  page = await browser.newPage();
  await page.goto('./');
  await page.waitForFunction(() => self.crossOriginIsolated);
  await page.evaluate(async () => {
    const load = (path: string) => import(/* @vite-ignore */ path);
    const [{ WasmRunner, coreUrls }, engine, model, settings, edits] = await Promise.all([
      load('/src/engine/wasm-runner.ts'),
      load('/src/engine/index.ts'),
      load('/src/model/operations.ts'),
      load('/src/model/settings.ts'),
      load('/src/model/edits.ts'),
    ]);
    const runner = new WasmRunner(coreUrls('ffmpeg/core-0.12.10/'));
    const make = async (name: string, args: string[], inputs: File[] = []) => {
      const r = await runner.run({ inputs, args: ['-hide_banner', '-y', ...args, `/out/${name}`], outputs: [name] });
      if (r.code !== 0) throw new Error(r.log.slice(-5).join('\n'));
      return new File([r.files.get(name)], name);
    };
    Object.assign(globalThis, { t: { runner, make, engine: engine.createEngine(runner), model, settings, edits } });
  });
});

test.afterAll(async () => {
  await page.close();
});

test('reads media info and the silences at the ends', async () => {
  const r = await page.evaluate(async () => {
    const { make, engine } = (globalThis as never as { t: Record<string, never> }).t as never as {
      make: (n: string, a: string[]) => Promise<File>;
      engine: { probe(f: File): Promise<unknown>; silences(f: File, i: unknown): Promise<unknown> };
    };
    // 1 s of silence, 5 s of tone, 2 s of silence.
    const wav = await make('gaps.wav', ['-f', 'lavfi', '-i', 'sine=f=440:d=5:sample_rate=48000', '-af', 'adelay=1000:all=1,apad=pad_dur=2', '-ac', '2', '-c:a', 'pcm_s24le']);
    const info = await engine.probe(wav);
    return { info, silences: await engine.silences(wav, info) };
  });
  expect(r.info).toMatchObject({
    container: 'wav',
    tracks: [{ kind: 'audio', index: 0, codec: 'pcm_s24le', channels: 2, sampleRate: 48000, bitDepth: 24 }],
    hasCover: false,
  });
  expect((r.info as { duration: number }).duration).toBeCloseTo(8, 1);
  const s = r.silences as { head: number; tail: number };
  expect(s.head).toBeCloseTo(1, 1);
  expect(s.tail).toBeCloseTo(6, 1);
});

test('processes the model plans in every format', async () => {
  const results = await page.evaluate(async () => {
    type T = {
      make: (n: string, a: string[], i?: File[]) => Promise<File>;
      runner: { run(r: unknown): Promise<{ log: string[] }> };
      engine: { probe(f: File): Promise<Record<string, never>>; process(l: string, f: File, i: unknown): { result: Promise<{ blob: Blob; extension: string; warnings: string[] }> } };
      model: { parseMeasurement(k: string, s: string): { i: number; tp: number } | null };
      settings: { defaultSettings(): unknown; effectiveSettings(b: unknown, o: unknown): unknown };
      edits: { defaultEdits(): Record<string, unknown> };
    };
    const { make, runner, engine, model, settings, edits } = (globalThis as never as { t: T }).t;
    const wav = await make('tone.wav', ['-f', 'lavfi', '-i', 'sine=f=440:d=20:sample_rate=48000', '-af', 'volume=-12dB', '-ac', '2', '-c:a', 'pcm_s24le']);
    const bare = await make('bare.mp3', ['-f', 'lavfi', '-i', 'sine=f=330:d=20:sample_rate=44100', '-c:a', 'libmp3lame', '-b:a', '192k']);
    const png = await make('cover.png', ['-f', 'lavfi', '-i', 'color=c=red:s=64x64', '-frames:v', '1']);
    const mp3 = await make('tono.mp3', ['-i', '/in/0/bare.mp3', '-i', '/in/1/cover.png', '-map', '0:a', '-map', '1:v', '-c', 'copy', '-disposition:v', 'attached_pic', '-metadata', 'title=Tono', '-id3v2_version', '3'], [bare, png]);
    const sources = { wav: [wav, await engine.probe(wav)], mp3: [mp3, await engine.probe(mp3)] } as const;

    const cases: [string, 'wav' | 'mp3', object, object][] = [
      ['default wav', 'wav', {}, {}],
      ['trim fades 16-bit', 'wav', { convert: { bitDepth: 16 } }, { in: 2, out: 12, fadeIn: { duration: 1, curve: 'qsin' }, fadeOut: { duration: 2, curve: 'exp' } }],
      ['lufs flac', 'wav', { normalize: { enabled: true }, convert: { format: 'flac' } }, {}],
      ['peak mp3 vbr', 'wav', { normalize: { enabled: true, mode: 'peak' }, convert: { format: 'mp3', sampleRate: 44100, mp3: { mode: 'vbr', bitrate: 320, quality: 2 } } }, {}],
      ['mp3 cover to mp3', 'mp3', { convert: { format: 'mp3' } }, { in: 1 }],
      ['mp3 to aac stereo', 'mp3', { convert: { format: 'aac', channels: 2 } }, {}],
      ['mp3 to flac 16', 'mp3', { convert: { format: 'flac', bitDepth: 16 } }, {}],
      ['opus', 'mp3', { convert: { format: 'opus' } }, {}],
      ['ogg without tags', 'mp3', { convert: { format: 'ogg', keepMetadata: false } }, {}],
      ['lossless mp3 trim', 'mp3', { trim: { lossless: true }, convert: { format: 'mp3' } }, { in: 3, out: 9 }],
      ['copy track', 'mp3', { extract: { mode: 'copy' } }, { in: 5 }],
    ];
    const out: Record<string, unknown> = {};
    for (const [name, src, own, e] of cases) {
      const [file, info] = sources[src];
      try {
        const input = { info, edits: { ...edits.defaultEdits(), ...e }, settings: settings.effectiveSettings(settings.defaultSettings(), own) };
        const r = await engine.process(name, file, input).result;
        const result = new File([r.blob], `result.${r.extension}`);
        const probed = await engine.probe(result);
        let loudness = null;
        if (name.startsWith('lufs') || name.startsWith('peak')) {
          const m = await runner.run({ inputs: [result], args: ['-hide_banner', '-i', `/in/0/${result.name}`, '-af', 'loudnorm=print_format=json', '-f', 'null', '-'], outputs: [] });
          loudness = model.parseMeasurement('loudnorm', m.log.join('\n'));
        }
        out[name] = { extension: r.extension, warnings: r.warnings, info: probed, loudness };
      } catch (err) {
        out[name] = { error: String((err as Error).message), detail: (err as { detail?: string }).detail };
      }
    }
    return out;
  });

  type Out = { extension: string; warnings: string[]; info: { duration: number; hasCover: boolean; tags: Record<string, string>; tracks: Record<string, unknown>[] }; loudness: { i: number; tp: number } | null };
  const r = results as Record<string, Out>;
  for (const [name, value] of Object.entries(r)) expect(value, `${name}: ${JSON.stringify(value)}`).not.toHaveProperty('error');

  const audio = (name: string) => r[name]!.info.tracks.find((t) => t.kind === 'audio');
  expect(audio('default wav')).toMatchObject({ codec: 'pcm_s24le', sampleRate: 48000, channels: 2, bitDepth: 24 });
  expect(r['trim fades 16-bit']!.info.duration).toBeCloseTo(10, 1);
  expect(audio('trim fades 16-bit')).toMatchObject({ codec: 'pcm_s16le', bitDepth: 16 });
  expect(audio('lufs flac')).toMatchObject({ codec: 'flac', sampleRate: 48000, bitDepth: 24 });
  expect(r['lufs flac']!.loudness!.i).toBeCloseTo(-14, 0);
  expect(audio('peak mp3 vbr')).toMatchObject({ codec: 'mp3', sampleRate: 44100 });
  expect(r['peak mp3 vbr']!.loudness!.tp).toBeLessThan(0);
  expect(r['mp3 cover to mp3']).toMatchObject({ extension: 'mp3', warnings: ['lossy-reencode'], info: { hasCover: true, tags: { title: 'Tono' } } });
  expect(r['mp3 cover to mp3']!.info.duration).toBeCloseTo(19, 1);
  expect(r['mp3 to aac stereo']).toMatchObject({ extension: 'm4a', info: { hasCover: true } });
  expect(audio('mp3 to aac stereo')).toMatchObject({ codec: 'aac', channels: 2 });
  expect(audio('mp3 to flac 16')).toMatchObject({ codec: 'flac', bitDepth: 16, sampleRate: 44100 });
  expect(r['opus']).toMatchObject({ extension: 'opus', warnings: ['lossy-reencode', 'rate-adjusted'] });
  expect(audio('opus')).toMatchObject({ codec: 'opus', sampleRate: 48000 });
  expect(r['ogg without tags']!.info.tags).toEqual({});
  expect(r['lossless mp3 trim']).toMatchObject({ extension: 'mp3', warnings: [], info: { hasCover: true } });
  expect(r['lossless mp3 trim']!.info.duration).toBeCloseTo(6, 0);
  expect(r['copy track']).toMatchObject({ extension: 'mp3', info: { hasCover: true } });
  expect(r['copy track']!.info.duration).toBeCloseTo(15, 0);
});

test('cancels a running job, keeps the screen on meanwhile, and runs the next one', async () => {
  const r = await page.evaluate(async () => {
    type View = { status: string; progress: number; error?: string };
    type T = {
      make: (n: string, a: string[]) => Promise<File>;
      engine: {
        probe(f: File): Promise<unknown>;
        process(l: string, f: File, i: unknown): { id: string; result: Promise<{ blob: Blob }> };
        queue: { cancel(id: string): void; jobs(): View[]; subscribe(l: (j: View[]) => void): () => void };
        wakeLock: { state(): string };
      };
      settings: { defaultSettings(): unknown; effectiveSettings(b: unknown, o: unknown): unknown };
      edits: { defaultEdits(): unknown };
    };
    const { make, engine, settings, edits } = (globalThis as never as { t: T }).t;
    const long = await make('long.wav', ['-f', 'lavfi', '-i', 'sine=f=220:d=180:sample_rate=48000', '-ac', '2', '-c:a', 'pcm_s16le']);
    const info = await engine.probe(long);
    const input = { info, edits: edits.defaultEdits(), settings: settings.effectiveSettings(settings.defaultSettings(), { convert: { format: 'mp3' } }) };

    const job = engine.process('long', long, input);
    let wake = '';
    let progressed = 0;
    await new Promise<void>((resolve) => {
      const stop = engine.queue.subscribe((jobs) => {
        const j = jobs.find((x) => x.status === 'running');
        if (j && j.progress > 0.05) {
          progressed = j.progress;
          wake = engine.wakeLock.state();
          stop();
          resolve();
        }
      });
    });
    const t0 = performance.now();
    engine.queue.cancel(job.id);
    const cancelled = await job.result.then(() => 'done', (e: { code: string }) => e.code);
    const next = engine.process('next', long, { ...input, edits: { ...(edits.defaultEdits() as object), out: 2 } });
    const blob = (await next.result).blob;
    // The result settles just before the queue marks itself idle.
    await new Promise((resolve) => setTimeout(resolve, 0));
    return { progressed, wake, cancelled, nextBytes: blob.size, nextMs: Math.round(performance.now() - t0), wakeAfter: engine.wakeLock.state() };
  });
  expect(r.progressed).toBeGreaterThan(0.05);
  expect(r.progressed).toBeLessThan(1);
  expect(r.wake).toBe('held');
  expect(r.cancelled).toBe('cancelled');
  expect(r.nextBytes).toBeGreaterThan(10_000);
  expect(r.wakeAfter).toBe('idle');
});
